export type VoiceSpeakerIdentityResult = { receipt: OperationReceipt; resolved_person_id: PersonId | null }
/**
 * The scope of one website activation rule. Exact rules match only the
 * normalized host; suffix rules also match its subdomains.
 */
export type WebsiteHostMatch = "exact" | "suffix"
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }
export type WorkflowEventKind = "meeting_finalized" | "meeting_started" | "speaker_renamed" | "audio_imported" | "document_ingested" | "calendar_meeting_detected" | "agent_hook_event" | "meeting_prompt_recorded" | "meeting_prompt_ignored" | "meeting_auto_record_started" | "meeting_auto_record_stopped" | "meeting_prep_presented" | "meeting_prep_record_armed" | "meeting_prep_brief_opened" | "meeting_prep_dismissed" | "meeting_wrap_presented" | "meeting_wrap_notes_opened" | "meeting_wrap_follow_up_copied" | "meeting_wrap_done" |
/**
 * The dictation history has runs the learning loops have not read yet.
 *
 * This is a wake-up, not data: it carries no transcript and its dedupe key
 * is one local day, so a heavy dictation day produces one event and one
 * bounded mining pass per loop rather than thousands.
 */
"dictation_corpus_swept" |
/**
 * A human corrected a dictation. Payload is the rewrite they performed;
 * the dedupe key is that rewrite on that local day.
 */
"dictation_correction_recorded" |
/**
 * The configured digest hour has passed on a local day the digest has not
 * summarized yet. Payload is that local day; the dedupe key is that local
 * day, so a restart at 19:00 cannot fire a second evening notification.
 */
"daily_digest_due"
export type WorkflowId = "person_linking" | "pre_meeting_briefing" | "continuity" | "vocabulary_mining" | "document_linking" |
/**
 * Loop 1. Mines the dictation corpus for spoken symbol phrases no
 * replacement rule covers yet.
 */
"spoken_punctuation" |
/**
 * Loop 2. Turns repeated human-authored rewrites into vocabulary
 * suggestions.
 */
"correction_learning" |
/**
 * Loop 5. Notices a mode the user keeps reaching for by shortcut.
 */
"mode_habits" |
/**
 * Loop 6. Reports capture-quality statistics worth acting on.
 */
"capture_advisor" |
/**
 * Internal projection that narrates meeting recording decisions. It is
 * permanently enabled and never appears in the Settings workflow list.
 */
"meeting_activity" |
/**
 * Loop 4. Assembles the session-scoped priming blob for a meeting in a
 * series with standing consent. Infrastructure, not a choice: it only ever
 * runs for a series the user has already said yes to, and its output dies
 * with the session.
 */
"series_priming" |
/**
 * D20. Shapes one evening sentence out of the day's receipts. It is
 * permanently enabled here and gated by `meeting_digest_enabled` at the
 * scheduler instead: the switch a person looks for lives on Settings >
 * Meetings beside the hour it fires at, and a second copy of it in the
 * workflow list would be a second thing to keep true.
 */
"daily_digest"
export type WorkflowJumpTarget = { kind: "meeting"; session_id: MeetingSessionId } | { kind: "document"; document_id: DocumentId }
export type WorkflowOutcomeCode = "person_links" | "briefing" | "continuity" | "vocabulary_candidates" | "document_links" |
/**
 * A learning loop finished a mining pass. `suggestions` counts what it
 * added to the pending queue this run, which is the only number a reader
 * can act on — a pass that mined a thousand runs and suggested nothing is
 * a quiet success, not an event.
 */
"learning_suggestions" |
/**
 * Loop 4 primed one session. `terms` counts what the session's own
 * transcription will see; nothing was written to shared vocabulary.
 */
"series_primed" |
/**
 * D20 shaped one evening's sentence. The three counts below are the
 * sentence: they are what the day held, not what this run changed —
 * the digest writes nothing.
 */
"digest_raised" | "prompt_recorded" | "prompt_ignored" | "auto_record_started" | "auto_record_stopped" | "prep_presented" | "prep_record_armed" | "prep_brief_opened" | "prep_dismissed" | "wrap_presented" | "wrap_notes_opened" | "wrap_follow_up_copied" | "wrap_done" | "already_processed" | "failed" | "skipped"
export type WorkflowOutcomeCounts = { changes: number; persons: number; series: number; carried: number; candidates: number; suggestions: number; terms: number;
/**
 * D20: meetings captured on the digest's local day.
 */
meetings: number;
/**
 * D20: open loops closed on the digest's local day.
 */
loops_closed: number;
/**
 * D20: learning suggestions still waiting for an answer at digest time.
 * Distinct from `suggestions`, which counts what a mining pass just added.
 */
suggestions_waiting: number;
/**
 * D27: open rows somebody else has owed for longer than a working week,
 * at digest time. A backlog like `suggestions_waiting`, not a day count.
 */
waiting_on_stale: number }
export type WorkflowRunCursor = { started_at_utc_ms: number; run_id: WorkflowRunId }
export type WorkflowRunId = string
export type WorkflowRunReceipt = { id: WorkflowRunId; workflow_id: WorkflowId; event_kind: WorkflowEventKind; jump_target: WorkflowJumpTarget | null; status: WorkflowRunStatus; started_at_utc_ms: number; finished_at_utc_ms: number; outcome_summary: string; outcome_code: WorkflowOutcomeCode; outcome_counts: WorkflowOutcomeCounts; error: string | null }
export type WorkflowRunStatus = "ok" | "failed" | "skipped"
export type WorkflowRunsRequest = { workflow_id: WorkflowId | null; cursor: WorkflowRunCursor | null; limit: number | null }
export type WorkflowSetEnabledRequest = { workflow_id: WorkflowId; enabled: boolean; expected_revision: number }
export type WorkflowSummary = { id: WorkflowId; enabled: boolean; last_run: WorkflowRunReceipt | null }
export type WorkflowsListResult = { schema_version: number; revision: number; entries: WorkflowSummary[] }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
